<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $db=db(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$a=$_POST['action']??'';if($a==='add'){$db->prepare('INSERT INTO suppliers(name,phone,address) VALUES(?,?,?)')->execute([trim($_POST['name']),trim($_POST['phone']??''),trim($_POST['address']??'')]);header('Location: suppliers.php?saved=1');exit;}if($a==='pay'){$sid=(int)$_POST['supplier_id'];$amount=(float)$_POST['amount'];$note=trim((string)($_POST['note']??''));if($amount<=0)throw new RuntimeException('Enter a valid payment amount.');$q=$db->prepare('SELECT COALESCE(SUM(subtotal-paid),0) FROM purchases WHERE supplier_id=?');$q->execute([$sid]);$due=(float)$q->fetchColumn();if($amount>$due+0.0001)throw new RuntimeException('Payment cannot exceed outstanding balance.');$db->beginTransaction();$remaining=$amount;$q=$db->prepare('SELECT id,subtotal,paid FROM purchases WHERE supplier_id=? AND subtotal>paid ORDER BY id');$q->execute([$sid]);$firstPurchaseId=null;foreach($q as $p){$open=(float)$p['subtotal']-(float)$p['paid'];$take=min($remaining,$open);if($take>0){if($firstPurchaseId===null)$firstPurchaseId=(int)$p['id'];$db->prepare('UPDATE purchases SET paid=paid+? WHERE id=?')->execute([$take,$p['id']]);$remaining-=$take;}if($remaining<=0)break;}$db->prepare('INSERT INTO supplier_payments(supplier_id,purchase_id,amount,note) VALUES(?,?,?,?)')->execute([$sid,$firstPurchaseId,$amount,$note!==''?$note:null]);$db->commit();audit_log('supplier_payment','Supplier #'.$sid.' payment Rs. '.number_format($amount,2).($note!==''?' · '.$note:''));header('Location: suppliers.php?paid=1');exit;}}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}}
$rows=$db->query('SELECT s.*,COALESCE((SELECT SUM(p.subtotal-p.paid) FROM purchases p WHERE p.supplier_id=s.id),0) due,COALESCE((SELECT SUM(p.subtotal) FROM purchases p WHERE p.supplier_id=s.id),0) purchases_total FROM suppliers s ORDER BY s.name')->fetchAll();$payments=$db->query('SELECT sp.*,s.name supplier,p.invoice_no FROM supplier_payments sp JOIN suppliers s ON s.id=sp.supplier_id LEFT JOIN purchases p ON p.id=sp.purchase_id ORDER BY sp.id DESC LIMIT 100')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Suppliers</title><link rel="stylesheet" href="style.css"><style>.pay-form{display:grid;grid-template-columns:110px 1fr auto;gap:7px;align-items:center}.pay-form input{min-width:0}.statement-actions{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:15px}.supplier-statement{margin-top:20px}.supplier-statement select{padding:9px;min-width:220px}@media(max-width:700px){.pay-form{grid-template-columns:1fr}.pay-form .btn{width:100%}}</style></head><body><header><div class="brand">💊 <?=e(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a href="inventory.php">Inventory</a><a class="active" href="manage.php">Management</a></nav></header><main><div class="page-title"><div><div class="eyebrow">SUPPLIERS</div><h1>Suppliers</h1><p>Manage suppliers, purchases, payments and outstanding balances.</p></div></div><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="success">✓ Supplier added.</div><?php endif;?><?php if(isset($_GET['paid'])):?><div class="success">✓ Supplier payment recorded and allocated against outstanding purchases.</div><?php endif;?><section class="panel"><h2>Add Supplier</h2><form method="post" class="grid"><input type="hidden" name="action" value="add"><label>Name<input name="name" required></label><label>Phone<input name="phone"></label><label>Address<input name="address"></label><button class="btn">Save Supplier</button></form></section><section class="panel"><h2>Supplier Balances</h2><table><tr><th>Supplier</th><th>Phone</th><th>Total Purchases</th><th>Outstanding</th><th>Pay Supplier</th></tr><?php foreach($rows as $r):$purchaseTotal=(float)$r['purchases_total'];$due=(float)$r['due'];?><tr><td><b><?=e($r['name'])?></b></td><td><?=e($r['phone'])?></td><td>Rs. <?=money($purchaseTotal)?></td><td><b>Rs. <?=money($due)?></b></td><td><?php if($due>0):?><form method="post" class="pay-form"><input type="hidden" name="action" value="pay"><input type="hidden" name="supplier_id" value="<?=$r['id']?>"><input name="amount" type="number" min="0.01" max="<?=e((string)$due)?>" step="0.01" placeholder="Amount" required><input name="note" maxlength="255" placeholder="Note (optional)"><button class="btn">Pay Supplier</button></form><?php else:?><span>Paid</span><?php endif;?></td></tr><?php endforeach;?></table></section><section class="panel supplier-statement"><h2>Supplier Payment History</h2><p>Every payment made to a supplier is recorded here separately from purchases and does not change inventory.</p><table><tr><th>Date</th><th>Supplier</th><th>Amount</th><th>Purchase Reference</th><th>Note</th></tr><?php foreach($payments as $p):?><tr><td><?=e($p['created_at'])?></td><td><b><?=e($p['supplier'])?></b></td><td><b>Rs. <?=money((float)$p['amount'])?></b></td><td><?=e($p['invoice_no']??'Supplier account')?></td><td><?=e($p['note']??'')?></td></tr><?php endforeach;if(!$payments):?><tr><td colspan="5">No supplier payments recorded yet.</td></tr><?php endif;?></table></section></main></body></html>